export const mat2Tasks={"internal": [{"id": "compare", "title": "Compare and explain", "kind": "internal", "type": "compare", "cases": [["0", "Internal energy includes…", ["Total particle kinetic and potential energy", "Only temperature readings", "Only motion of the whole container"], 0, "Internal energy includes both microscopic contributions."], ["1", "Temperature is related to…", ["Total energy regardless of sample size", "Average particle kinetic energy", "Only particle diameter"], 1, "Average kinetic energy and total internal energy differ."], ["2", "During ideal melting, added energy mainly changes…", ["Temperature without changing state", "Particle chemical identities", "Particle arrangement/potential energy"], 2, "Temperature remains constant during the phase change."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "internal-data", "type": "numeric", "prompt": "A fresh0.25 kg single-phase sample with c=1200 J/(kg°C) gains1800 J. Calculate its temperature rise.", "answer": 6, "unit": "°C", "reasonChoices": ["1800 ÷ (0.25 × 1200)", "1800 × 0.25 × 1200", "1200 ÷ (1800 × 0.25)"], "reason": 0, "why": "Use the stated conditions, relationship and units."}, {"id": "model", "title": "Predict and compare every setting", "kind": "internal-model", "type": "experiment", "experiment": "internal", "why": "Check the conditions and energy or pressure account."}], "latent": [{"id": "compare", "title": "Compare and explain", "kind": "latent", "type": "compare", "cases": [["0", "Specific latent heat is energy needed to change the state of…", ["1 kg without changing temperature", "Any sample by1°C", "One molecule into a different element"], 0, "The definition uses unit mass and no temperature change."], ["1", "The state-change equation is…", ["E=m/L", "E=mL", "E=L/m"], 1, "Multiply mass by specific latent heat."], ["2", "Specific latent heat of fusion concerns…", ["Only liquid and gas", "Only temperature rise in gas", "Solid and liquid"], 2, "Fusion covers melting/freezing."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "latent-data", "type": "numeric", "prompt": "A fresh0.15 kg sample changes state using4500 J. Calculate its specific latent heat.", "answer": 30000, "unit": "J/kg", "reasonChoices": ["4500 ÷ 0.15", "4500 × 0.15", "0.15 ÷ 4500"], "reason": 0, "why": "Use the stated conditions, relationship and units."}, {"id": "model", "title": "Predict and compare every setting", "kind": "latent-model", "type": "experiment", "experiment": "latent", "why": "Check the conditions and energy or pressure account."}], "curves": [{"id": "compare", "title": "Compare and explain", "kind": "curves", "type": "compare", "cases": [["0", "A horizontal heating-curve region can mean…", ["Energy is changing state at constant temperature", "No energy is entering", "All particles have stopped moving"], 0, "A state change still transfers energy."], ["1", "A sloping single-phase region represents…", ["A compulsory chemical reaction", "Temperature changing", "Particles increasing in diameter"], 1, "Temperature changes with average kinetic energy."], ["2", "On a cooling plateau, internal energy…", ["Must stay constant", "Increases because the curve is flat", "Decreases while temperature stays constant"], 2, "Energy leaves during freezing/condensing."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "curves-data", "type": "numeric", "prompt": "A fresh state-change plateau lasts40 s with constant250 W input. Calculate energy transferred.", "answer": 10000, "unit": "J", "reasonChoices": ["250 × 40", "250 ÷ 40", "40 ÷ 250"], "reason": 0, "why": "Use the stated conditions, relationship and units."}, {"id": "model", "title": "Predict and compare every setting", "kind": "curves-model", "type": "experiment", "experiment": "curves", "why": "Check the conditions and energy or pressure account."}], "gas": [{"id": "compare", "title": "Compare and explain", "kind": "gas", "type": "compare", "cases": [["0", "A gas’s molecules are in…", ["Constant random motion", "Only fixed-position vibration", "One permanent clockwise stream"], 0, "The motion is disordered."], ["1", "At fixed volume and mass, warming generally makes pressure…", ["Decrease", "Increase", "Remain fixed regardless of temperature"], 1, "Average kinetic energy rises and wall impacts change."], ["2", "Gas temperature is related to…", ["Individual molecule diameter", "Only the mass of the vessel", "Average molecular kinetic energy"], 2, "It is an average, not identical molecular velocities."]]}, {"id": "sequence", "title": "Build the explanation in order", "kind": "gas-sequence", "type": "sequence", "why": "Connect energy, motion, impacts and pressure.", "route": ["heat", "energy", "motion", "impacts", "pressure"], "labels": ["Transfer energy into gas", "Average kinetic energy increases", "Average molecular speed increases", "Wall impacts are more frequent and stronger", "Pressure rises at fixed volume"]}, {"id": "model", "title": "Predict and compare every setting", "kind": "gas-model", "type": "experiment", "experiment": "gas", "why": "Check the conditions and energy or pressure account."}], "compression": [{"id": "compare", "title": "Compare and explain", "kind": "compression", "type": "compare", "cases": [["0", "For a fixed mass at constant temperature…", ["pV is constant", "p/V is always constant", "pV stays constant at every changing temperature"], 0, "The temperature condition is essential."], ["1", "Halving gas volume at constant temperature makes pressure…", ["Halve", "Double", "Remain unchanged"], 1, "p₁V₁=p₂V₂."], ["2", "A pressure force on a flat container wall acts…", ["Only parallel to the wall", "Only along the direction of gravity", "At right angles to the surface"], 2, "Pressure acts normal to the surface."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "compression-data", "type": "numeric", "prompt": "A fresh fixed gas at80000 Pa occupies0.006 m³. At constant temperature, volume becomes0.004 m³. Calculate final pressure.", "answer": 120000, "unit": "Pa", "reasonChoices": ["80000 × 0.006 ÷ 0.004", "80000 × 0.004 ÷ 0.006", "80000 ÷ (0.006 × 0.004)"], "reason": 0, "why": "Use the stated conditions, relationship and units."}, {"id": "model", "title": "Predict and compare every setting", "kind": "compression-model", "type": "experiment", "experiment": "compression", "why": "Check the conditions and energy or pressure account."}, {"id": "work", "title": "Higher: explain work and gas temperature", "kind": "work", "type": "compare", "higher": true, "cases": [["0", "Rapid, approximately insulated compression can…", ["Warm gas as work increases internal energy", "Always keep gas temperature fixed", "Destroy gas particles"], 0, "Work transfers energy to the gas."], ["1", "Compression while temperature is maintained constant requires…", ["No interaction with surroundings ever", "Energy transfer out balancing the work input", "Increasing particle diameter"], 1, "The maintained-temperature boundary differs from an insulated pump."], ["2", "For a pump case that warms the gas, pV constant…", ["Still applies with no qualification", "Proves all gas motion has stopped", "Cannot be applied as a constant-temperature relation"], 2, "Temperature has changed; keep the assumptions explicit."]]}]};
export const experimentOptions={"internal": {"a": [["warm", "Single-phase warming"], ["melt", "Melting at transition"]], "b": [["40", "40 J input"], ["80", "80 J input"]], "labels": ["Energy-transfer situation", "Input energy"], "unit": "energy part and temperature", "choices": [["ke-up", "Kinetic energy rises / temperature rises"], ["pe-up", "Potential energy rises / temperature unchanged"], ["none", "Internal energy unchanged"]]}, "latent": {"a": [["fusion", "Fusion: L10000 J/kg"], ["vapor", "Vaporisation: L20000 J/kg"]], "b": [["0.1", "0.1 kg"], ["0.2", "0.2 kg"]], "labels": ["Toy-material state change", "Mass changing state"], "unit": "J required energy"}, "curves": {"a": [["heat", "Heating: input1000 W"], ["cool", "Cooling: remove1000 W"]], "b": [["5", "5 s elapsed"], ["15", "15 s elapsed"], ["50", "50 s elapsed"], ["90", "90 s elapsed"], ["110", "110 s elapsed"]], "labels": ["Direction (1 kg toy sample)", "Elapsed model time"], "unit": "°C temperature"}, "gas": {"a": [["20", "Initially20°C"], ["60", "Initially60°C"]], "b": [["warm", "Warm by10°C"], ["cool", "Cool by10°C"]], "labels": ["Initial gas temperature", "Energy-transfer direction (rigid sealed box)"], "unit": "average KE and pressure", "choices": [["rise", "Both rise"], ["fall", "Both fall"], ["size", "Molecules enlarge instead"]]}, "compression": {"a": [["0.002", "0.002 m³ final"], ["0.008", "0.008 m³ final"]], "b": [["100000", "100000 Pa initial"], ["200000", "200000 Pa initial"]], "labels": ["Final gas volume (initial0.004 m³)", "Initial absolute pressure"], "unit": "Pa final pressure"}};

export const tasksForMat2=(k,tier='Higher')=>mat2Tasks[k].filter(t=>!t.higher||tier==='Higher');
export const validMat2=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const numericMat2=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;export const advanceMat2=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;
export const toy={c:1000,fusion:10000,vapor:20000,melt:20,boil:80,mass:1,power:1000};
export function internalAccount(mode,input){if(!['warm','melt'].includes(mode)||!Number.isFinite(input)||input<0)throw new RangeError('Use warming/melting and finite nonnegative energy.');let kinetic=100+(mode==='warm'?input:0),potential=100+(mode==='melt'?input:0);return{kinetic,potential,total:kinetic+potential,input,temperature:mode==='warm'?'rises':'unchanged'};}
export function heatingAt(t,direction='heat'){if(!Number.isFinite(t)||t<0||t>120||!['heat','cool'].includes(direction))throw new RangeError('Use elapsed0–120s and heating/cooling.');let x=direction==='heat'?t:120-t,temperature=x<10?10+x:x<20?20:x<80?x:x<100?80:x-20,phase=x<10?'solid':x<20?(direction==='heat'?'melting':'freezing'):x<80?'liquid':x<100?(direction==='heat'?'vaporising':'condensing'):'gas';return{temperature,phase,time:t,energy:t*1000,fraction:x<10?0:x<20?(x-10)/10:x<80?1:x<100?(x-80)/20:1};}
export function compressedPressure(p,V){if(!Number.isFinite(p)||p<=0||!Number.isFinite(V)||V<=0)throw new RangeError('Positive finite absolute pressure and volume.');return p*.004/V;}
export function experimentResult(k,a,b){let o=experimentOptions[k];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===String(b)))throw new RangeError('Choose stated settings.');if(k==='internal')return{...internalAccount(a,+b),value:a==='warm'?'ke-up':'pe-up',a,b};if(k==='latent')return{L:a==='fusion'?toy.fusion:toy.vapor,mass:+b,temperature:a==='fusion'?toy.melt:toy.boil,value:(a==='fusion'?toy.fusion:toy.vapor)*Number(b),a,b};if(k==='curves')return{...heatingAt(+b,a),value:heatingAt(+b,a).temperature,a,b};if(k==='gas')return{initial:+a,final:+a+(b==='warm'?10:-10),value:b==='warm'?'rise':'fall',a,b};return{p1:+b,V1:.004,V2:+a,value:compressedPressure(+b,+a),a,b};}
export const predictionValid=(k,v,r)=>experimentOptions[k].choices?v===r.value:numericMat2(v,r.value);
export const outputLabel=(k,v)=>experimentOptions[k].choices?.find(x=>x[0]===v)?.[1]??Number(Number(v).toFixed(3))+' '+experimentOptions[k].unit;
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));export const experimentValid=(k,v)=>experimentCases(k).every(x=>v.observed?.includes(x))&&v.interpretation==='limited';
